import puppeteer from 'puppeteer';
import { createWriteStream, readFileSync } from "fs"
import { sportNameMap } from "../sportNameMap.js";
import { tournamentNameMap } from "../tournamentName/CS2/Map.js";
import { marketNameMap } from "../marketNameMap.js";
import { stripTeamName } from "../util/stripTeamName.js";

// generated by chatGPT https://chatgpt.com/c/a9300588-42f8-40ee-bff4-b00c945cee1e
function convDatetimeToISO(dateStr){

  // Parse the date string and create a Date object
  const parseDateStr = (dateStr) => {
    const [datePart, timePart] = dateStr.split(' ');
    const [month, day] = datePart.split('/');
    const [hours, minutes] = timePart.split(':');
  
    const date = new Date();
    date.setMonth(parseInt(month) - 1); // Months are zero-based in JavaScript
    date.setDate(parseInt(day));
    date.setHours(parseInt(hours));
    date.setMinutes(parseInt(minutes));
    date.setSeconds(0);
    date.setMilliseconds(0);
  
    return date;
  };
  
  const date = parseDateStr(dateStr);
  
  // Format the date as ISO 8601
  return date.toISOString();
}

export async function handleURL_esb(data, url){
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--disable-web-security']
  });  
  
  // load the book-specific mappings from json files
  const bookAbbrev = 'esb';
  const sportNameMappingPath = `books/${bookAbbrev}/sportNameMapping.json`;
  let sportNameMapping;
  try{
    sportNameMapping = Object.freeze(JSON.parse(readFileSync(sportNameMappingPath)));
  } catch (error){
    log.write(`Failure! Cannot open file ${sportNameMappingPath}\n`);
  }
  const tournamentNameMappingPath = `books/${bookAbbrev}/tournamentNameMapping.json`;
  let tournamentNameMapping;
  try{
    tournamentNameMapping = Object.freeze(JSON.parse(readFileSync(tournamentNameMappingPath)));
  } catch (error){
    log.write(`Failure! Cannot open file ${tournamentNameMappingPath}\n`);
  }
  const marketNameMappingPath = `books/${bookAbbrev}/marketNameMapping.json`;
  let marketNameMapping;
  try{
    marketNameMapping = Object.freeze(JSON.parse(readFileSync(marketNameMappingPath)));
  } catch (error){
    log.write(`Failure! Cannot open file ${marketNameMappingPath}\n`);
  }

  // open a file for logging
  const logFilePath = `books/${bookAbbrev}/log.txt`
  const log = createWriteStream(logFilePath);

  try{
//console.log('data: ');
//console.log(JSON.stringify(data, null, 2));
    let page = await browser.newPage();    
    page.setViewport({width:1000, height:1000})
    await page.goto(url);
  
    let selector, el, mapping;
    // get sport
    selector = 'div.oPInfo';
    const infoHandle = await page.waitForSelector(selector);
    let sportName = await infoHandle.$eval('img', e => e.getAttribute('src').split('/').pop().split('.')[0]);
    mapping = sportNameMapping.mapping.find( m => m.specificName === sportName);
    if(mapping){
      sportName = sportNameMap[mapping.globalID];;
    } else{
      log.write(`Failure! sportName Mapping of '${sportName}' does not exist in ${sportNameMappingPath}\n`);
      return;
    }
//console.log('>>>>>>>>>>>>>>> scraped sportName: ' + sportName);
    let sport = data.sports.findLast(s => s.name === sportName);
    if(!sport){
      /* sport is new */
      data.sports.push({ name: sportName, tournaments: [] });
      sport = data.sports.findLast(s => s.name === sportName);
    }
//console.log('sport: ');
//console.log(JSON.stringify(sport, null, 2));

    // get tournament
    selector = 'div.leagueName';
    let tournamentName = await infoHandle.$eval(selector, e => e.textContent.trim().replace(/\u00a0/, '\u0020'));
    mapping = tournamentNameMapping.mapping.find( m => m.specificName === tournamentName);
    if(mapping){
      tournamentName = tournamentNameMap[mapping.globalID];;
    } else{
      log.write(`Failure! tournamentName Mapping of '${tournamentName}' does not exist in ${tournamentNameMappingPath}\n`);
      return;
    }
//console.log('>>>>>>>>>>>>>>> scraped tournamentname: ' + tournamentName);
    let tournament = sport.tournaments.findLast(t => t.name === tournamentName );
    if(!tournament){
      /* tournament is new */
      sport.tournaments.push({ name: tournamentName, matches: [] });
      tournament = sport.tournaments.findLast(t => t.name === tournamentName);
    }
//console.log('tournament: ');
//console.log(JSON.stringify(tournament, null, 2));

    // get teamHome, teamAway
    selector = 'div.lDTeamName';
    const teams = await page.$$eval(selector, elements => elements.map( e => e.textContent.trim() ));
    const teamHome = stripTeamName(teams[0]);
    const teamAway = stripTeamName(teams[1])
//console.log('>>>>>>>>>>>>>>> scraped teamHome: ' + teamHome);
//console.log('>>>>>>>>>>>>>>> scraped teamAway: ' + teamAway);
    
    // get datetime, mode
    selector = 'div.matchStatus';
    el = await infoHandle.$eval(selector, e => e.textContent.trim().replace(/\u00a0/, '\u0020'));
    const datetime = convDatetimeToISO(el.split('B')[0].trim());
//console.log('>>>>>>>>>>>>>>> scraped datetime: ' + datetime);
    let mode = el.split('B')[1];
    mode = 'B' + mode;    
//console.log('>>>>>>>>>>>>>>> scraped mode: ' + mode);

    let match = tournament.matches.findLast(m =>
        m.teamHome === teamHome &&
        m.teamAway === teamAway &&
        m.datetime === datetime
    )
    if(!match){
      /* tournament is new */
      tournament.matches.push({ 
        teamHome: teamHome,
        teamAway: teamAway,
        datetime: datetime,
        urls: [],
        markets: []
      });
      match = tournament.matches.findLast(m =>
          m.teamHome === teamHome &&
          m.teamAway === teamAway &&
          m.datetime === datetime
      );
    }
    match.urls.push({book: 'Esportsbet', url: url});
//console.log('match: ');
//console.log(JSON.stringify(match, null, 2));

    // GET ALL THE MARKETS > ODDS > COEFS FOR THIS MATCH
    let market, odd, coef;
    selector = 'div.matchWrp';
    let marketHandles = await page.$$(selector);
//console.log(`$$${selector} length: ${marketHandles.length}`);
    // scroll until no more elements are loaded
    let old_size, new_size;
    do{
      old_size =  marketHandles.length;
      await marketHandles[marketHandles.length-1].scrollIntoView();
      await page.waitForNetworkIdle({idleTime: 500});
      marketHandles = await page.$$(selector);
//      console.log(`$$${selector} length: ${marketHandles.length}`);
      new_size =  marketHandles.length;
    } while( old_size !== new_size );
    selector = 'div.marketRow';
    const labelsHandle = await page.$(selector);
    selector = 'label';
    const labels = await labelsHandle.$$eval(selector, es => es.map( e => e.textContent));
    const labelHome = labels[0];
    const labelAway = labels[1];
    for(const marketHandle of marketHandles){
      // get marketName
      selector = 'div.matchInfoLeft';
      let marketName = await marketHandle.$eval(selector, e => e.textContent.trim());
      const HdpSpecial = marketName.split(' Hdp: ');
      if(HdpSpecial.length > 1){ marketName = 'Match Handicap' }
      mapping = marketNameMapping.mapping.find( m => m.specificName === marketName);
      if(mapping){
        marketName = marketNameMap[mapping.globalID];
      } else{
        log.write(`Warning! marketName Mapping of '${marketName}' does not exist in ${marketNameMappingPath}\n`);
      }
//console.log('>>>>>>>>>>>>>>> scraped marketName: ' + marketName);
      market = match.markets.findLast(m => m.name === marketName);
      if(!market){
        match.markets.push({name: marketName, odds: []});
        market = match.markets.findLast(m => m.name === marketName);
      }
//console.log('market: ');
//console.log(JSON.stringify(market, null, 2));
      // get odds
      selector = 'div.oddsWrp';
      const oddsHandles = await marketHandle.$$(selector);
//console.log(`$$${selector} length: ${oddsHandles.length}`);
      for(let i = 0; i < oddsHandles.length; i++){
        const oddHandle = oddsHandles[i];
        let oddName;
        const has_label = await oddHandle.$('label');
        if(has_label){
          oddName = await page.evaluate(e => e.textContent ,has_label);
        } else{
          // if no_label that means append its content at the end of oddName
          const sufix = await oddHandle.$eval('div.odds', e => e.textContent.trim())
          market.name = market.name + sufix;
          continue;
        }
        oddName = oddName
          .replace(labelHome, teamHome)
          .replace(labelAway, teamAway)
          .replace(/\+/g, '');
        if(HdpSpecial.length > 1){
          /* Match Handicaps are named like this: "BO3 Hdp: VP -1.5". They have exactly 2 odd entries.
          Note: The team in the is not always the first one listed */
          const isFromTitle = HdpSpecial[1].replace(labelHome, teamHome).replace(labelAway, teamAway).includes(oddName);
          if(isFromTitle){
            oddName = HdpSpecial[1].replace(labelHome, teamHome).replace(labelAway, teamAway);
          } else{
            const hdpValue = -1.0 * parseFloat(HdpSpecial[1].split(' ')[1]);
            const isHomeinTitle = HdpSpecial[1].includes(labelHome);
            oddName = `${isHomeinTitle ? teamAway : teamHome} ${hdpValue}`;
          }
        }
        /* First to reach Rounds are each a separate market, they have to merged into 1
        "Game 1 First to Win X Rounds", where X in {5,10} 
        is included in HdpSpecial[0] even after marketName has been mapped
        the X has to be appended along with a space to oddName */
        if(HdpSpecial[0].includes('First to Win 5 Rounds')){
          oddName = `${oddName} 5`;
        } else if(HdpSpecial[0].includes('First to Win 10 Rounds')){
          oddName = `${oddName} 10`;
        }
//console.log('>>>>>>>>>>>>>>> scraped oddName: ' + oddName);
        odd = market.odds.findLast(o => o.name === oddName);
        if(!odd){
          market.odds.push({name: oddName, coefs: []})
          odd = market.odds.findLast(o => o.name === oddName);
        }
        // value = null if an odd is locked
        const is_unlocked = await oddHandle.$eval('div.odds', e => {
          e = e.querySelector('label').nextSibling;
          return e ? parseFloat(e.textContent) : null;
        });
        const value = is_unlocked ? parseFloat(is_unlocked) : null;
//console.log('>>>>>>>>>>>>>>> scraped value: ' + value);
        coef = odd.coefs.findLast(c => c.book === 'Esportsbet');
        if(!coef){
          odd.coefs.push({book: 'Esportsbet', value: value});
        }
//console.log('market: ');
//console.log(JSON.stringify(market, null, 2));
      }
    }

  log.write(`Success! scraping a match from ${url}\n`);
  return 0;    

  } catch (error){
    log.write(`Critical Failure! scraping a match from ${url}\n`);
    return -1;
  } finally{
    await browser?.close();
  }
  
}